    op.drop_column('account', 'Birthdate')
    op.drop_column('account', 'Hashed_Password')
    op.drop_column('account', 'Phone')
    op.drop_column('account', 'Email')
    op.drop_column('account', 'Username')
    op.drop_column('account', 'AccountID')
